let colors = ['#F7FCE6', '#3151AE', '#2abde4', '#F8747F', '#f5d776'];
let ctx;
let mainRects = [];
let subRects = [];

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	divideRect1(width / 2, height / 2, width * 2, height * 2, 5, mainRects);

	background('#FDC4CB');

	for (let r of mainRects) {
		divideRect2(r.x, r.y, r.w * 0.7, r.h * 0.7, width * 0.05, subRects);
	}

	push();
	translate(width / 2, height / 2);
	rotate(PI / 6);
	shearX(-PI / 6);
	scale(sqrt(2) / sqrt(3), sqrt(2) / 2);
	translate(-width / 2, -height / 2);

	push();
	let lineDashPattern = [width * 0.01, width * 0.01];
	drawingContext.setLineDash(lineDashPattern);
	noFill();
	stroke('#ffffff');
	strokeWeight(width * 0.003);
	for (let m of mainRects) {
		rect(m.x, m.y, m.w * 0.9, m.h * 0.9);
	}
	pop();

	for (let s of subRects) {
		drawPrism(s.x, s.y, s.w * 0.9, s.h * 0.9, width * random(0.15, 0.04));
	}
	pop();
}

