function divideRect1(x, y, w, h, n, arr) {
	n--;
	if (n >= 0) {
		let w1 = w * random(0.25, 0.75);
		let h1 = h * random(0.25, 0.75);
		let w2 = w - w1;
		let h2 = h - h1;
		let rnd = 1;
		if (rnd == 0) {
			divideRect1(x - (w / 2) + (w1 / 2), y - (h / 2) + (h1 / 2), w1, h1, n, arr);
			divideRect1(x + (w / 2) - (w2 / 2), y - (h / 2) + (h1 / 2), w2, h1, n, arr);
			divideRect1(x + (w / 2) - (w2 / 2), y + (h / 2) - (h2 / 2), w2, h2, n, arr);
			divideRect1(x - (w / 2) + (w1 / 2), y + (h / 2) - (h2 / 2), w1, h2, n, arr);
		} else {
			if (w > h) {
				divideRect1(x - (w / 2) + (w1 / 2), y, w1, h, n, arr);
				divideRect1(x + (w / 2) - (w2 / 2), y, w2, h, n, arr);
			} else {
				divideRect1(x, y - (h / 2) + (h1 / 2), w, h1, n, arr);
				divideRect1(x, y + (h / 2) - (h2 / 2), w, h2, n, arr);
			}
		}
	} else {
		arr.push({ x: x, y: y, w: w, h: h });
	}
}

function divideRect2(x, y, w, h, minSide, arr) {
	let w1 = w * random(0.25, 0.75);
	let h1 = h * random(0.25, 0.75);
	let w2 = w - w1;
	let h2 = h - h1;
	if (minSide < max([w1, w2, h1, h2])) {
		if (w > h) {
			divideRect2(x - (w / 2) + (w1 / 2), y, w1, h, minSide, arr);
			divideRect2(x + (w / 2) - (w2 / 2), y, w2, h, minSide, arr);
		} else {
			divideRect2(x, y - (h / 2) + (h1 / 2), w, h1, minSide, arr);
			divideRect2(x, y + (h / 2) - (h2 / 2), w, h2, minSide, arr);
		}
	} else {
		arr.push({ x: x, y: y, w: w, h: h });
	}
}

function drawPrism(x, y, w, h, d) {
	push();

	let num = int(random(2, 5));
	let clr1 = random(colors);
	let clr2 = random(colors);

	while (clr1 == clr2) {
		clr1 = random(colors);
		clr2 = random(colors);
	}

	translate(x, y);
	fill(clr1);
	noStroke();
	rect(- d, - d, w + width * 0.0005, h + width * 0.0005);

	push();
	translate(0, h / 2);
	shearX(PI / 4)
	fill(clr1);
	rect(0, -d / 2, w, d);
	fill(clr2);
	tiling(0, -d / 2, w, d, int(w / random(14, 16)));
	pop();

	push();
	translate(w / 2, 0);
	shearY(PI / 4);
	fill(shadowColor(clr1));
	rect(-d / 2, 0, d, h);
	fill(shadowColor(clr2));
	tiling(-d / 2, 0, d, h, int(h / random(14, 16)));
	pop();
	pop();
}

function tiling(x, y, w, h, num) {
	let cols = num;
	let rows = int(cols * (h / w));
	if (w > h) {
		rows = cols
		cols = int(rows * (w / h));
	}
	let cellW = w / cols;
	let cellH = h / rows;
	push();
	translate(x - w / 2, y - h / 2);
	for (let i = 0; i < cols; i++) {
		for (j = 0; j < rows; j++) {
			let cellX = i * cellW + cellW / 2;
			let cellY = j * cellH + cellH / 2;
			rect(cellX, cellY, cellW / 2, cellH / 2);
		}
	}
	pop();
}

function shadowColor(clr) {
	let h = (hue(clr) - 7) % 360;
	let s = saturation(clr) - 3;
	let b = brightness(clr) - 30;
	let c = color(h, s, b);
	return c;
}

